<?php require_once '../config/db.php';require_once '../includes/auth.php';require_role('admin');$rows=$pdo->query("SELECT m.*,s.name subject_name FROM materials m JOIN subjects s ON s.id=m.subject_id WHERE m.material_type='question_paper' ORDER BY m.id DESC")->fetchAll();$page_title='Question Papers';$css_path='../assets/css/style.css';$home_path='dashboard.php';$logout_path='../logout.php';$role='admin';include '../includes/header.php';?><div class="layout"><?php include '../includes/sidebar.php';?><h1 class="page-title">Question Papers</h1><div class="table-card"><table><thead><tr><th>Title</th><th>Subject</th><th>Year/Description</th><th>File</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['title'])?></td><td><?=e($r['subject_name'])?></td><td><?=e($r['description'])?></td><td><a class="action-btn" href="../download.php?id=<?=$r['id']?>">View</a></td></tr><?php endforeach;?></tbody></table></div></main></div><?php include '../includes/footer.php';?>